final class GraphIo {
    static final List<String> SETTINGS =
        List.of("layering", "width", "promotion", "heuristic", "sweeps", "node_sep", "dummy_sep",
                "layer_gap", "direction", "sifting", "reduce", "restarts", "seed");
    record Pair(int first, int second) {}
    record InputLine(int number, String[] fields) {}
    record Error(String kind, int line) {}
    static final class Settings {
        String layering = "longest", heuristic = "barycenter", direction = "TB";
        int width = 4, sweeps = 12, nodeSep = 2, dummySep = 1, layerGap = 3, restarts;
        long seed = 1;
        boolean promotion, sifting, reduce;
        Settings() {}
        Settings(Settings source) {
            layering = source.layering;
            heuristic = source.heuristic;
            direction = source.direction;
            width = source.width;
            sweeps = source.sweeps;
            nodeSep = source.nodeSep;
            dummySep = source.dummySep;
            layerGap = source.layerGap;
            restarts = source.restarts;
            seed = source.seed;
            promotion = source.promotion;
            sifting = source.sifting;
            reduce = source.reduce;
        }
        boolean set(String name, String value) {
            if (Set.of("layering", "heuristic", "direction", "promotion", "sifting", "reduce")
                    .contains(name)) {
                boolean valid = switch (name) {
                    case "layering" -> Set.of("longest", "coffman").contains(value);
                    case "heuristic" -> Set.of("barycenter", "median").contains(value);
                    case "direction" -> Set.of("TB", "BT", "LR", "RL").contains(value);
                    default -> Set.of("on", "off").contains(value);
                };
                if (!valid)
                    return false;
                switch (name) {
                case "layering":
                    layering = value;
                    break;
                case "heuristic":
                    heuristic = value;
                    break;
                case "direction":
                    direction = value;
                    break;
                case "promotion":
                    promotion = value.equals("on");
                    break;
                case "sifting":
                    sifting = value.equals("on");
                    break;
                case "reduce":
                    reduce = value.equals("on");
                    break;
                }
                return true;
            }
            if (!SETTINGS.contains(name) || value.isEmpty() || value.length() > 10)
                return false;
            for (char c : value.toCharArray())
                if (c < '0' || c > '9')
                    return false;
            long number = Long.parseLong(value);
            long low = switch (name) {
                case "sweeps", "restarts" -> 0;
                case "layer_gap" -> 2;
                default -> 1;
            }, high = switch (name) {
                case "width" -> 40;
                case "sweeps" -> 50;
                case "seed" -> 2147483646L;
                default -> 9;
            };
            if (number < low || number > high)
                return false;
            switch (name) {
            case "width":
                width = (int)number;
                break;
            case "sweeps":
                sweeps = (int)number;
                break;
            case "node_sep":
                nodeSep = (int)number;
                break;
            case "dummy_sep":
                dummySep = (int)number;
                break;
            case "layer_gap":
                layerGap = (int)number;
                break;
            case "restarts":
                restarts = (int)number;
                break;
            case "seed":
                seed = number;
                break;
            }
            return true;
        }
        String value(String name) {
            return switch (name) {
                case "layering" -> layering;
                case "width" -> Integer.toString(width);
                case "promotion" -> promotion ? "on" : "off";
                case "heuristic" -> heuristic;
                case "sweeps" -> Integer.toString(sweeps);
                case "node_sep" -> Integer.toString(nodeSep);
                case "dummy_sep" -> Integer.toString(dummySep);
                case "layer_gap" -> Integer.toString(layerGap);
                case "direction" -> direction;
                case "sifting" -> sifting ? "on" : "off";
                case "reduce" -> reduce ? "on" : "off";
                case "restarts" -> Integer.toString(restarts);
                default -> Long.toString(seed);
            };
        }
    }
    static final class Graph {
        String name;
        Settings settings;
        Map<Integer, String> nodes = new TreeMap<>();
        List<Pair> edges = new ArrayList<>();
        Set<Pair> edgeSet = new HashSet<>();
        Pair path;
        int selfLoops, duplicates;
        Error error;
        Graph(String name, Settings defaults) {
            this.name = name;
            settings = new Settings(defaults);
        }
        String accept(String[] f) {
            if (f[0].equals("OPTION"))
                return settings.set(f[1], f[2]) ? null : "bad_option";
            int first = Integer.parseInt(f[1]);
            if (f[0].equals("NODE")) {
                if (nodes.containsKey(first))
                    return "duplicate_node";
                if (nodes.size() == 40)
                    return "too_many_nodes";
                nodes.put(first, f[2]);
                return null;
            }
            int second = Integer.parseInt(f[2]);
            if (!nodes.containsKey(first) || !nodes.containsKey(second))
                return "unknown_node";
            Pair pair = new Pair(first, second);
            if (f[0].equals("PATH"))
                path = pair;
            else if (first == second)
                selfLoops++;
            else if (!edgeSet.add(pair))
                duplicates++;
            else
                edges.add(pair);
            return null;
        }
    }
    static List<InputLine> lines(String name) throws Exception {
        List<InputLine> records = new ArrayList<>();
        List<String> lines = Files.readAllLines(Path.of("input", name), StandardCharsets.US_ASCII);
        for (int i = 0; i < lines.size(); i++)
            if (!lines.get(i).isEmpty() && !lines.get(i).startsWith("#"))
                records.add(new InputLine(i + 1, lines.get(i).split(" ")));
        return records;
    }
    static Settings defaults() throws Exception {
        Settings settings = new Settings();
        for (InputLine line : lines("params.txt"))
            settings.set(line.fields()[0], line.fields()[1]);
        return settings;
    }
    static List<Graph> graphs(Settings defaults) throws Exception {
        List<Graph> graphs = new ArrayList<>();
        Graph graph = null;
        for (InputLine line : lines("graphs.txt")) {
            String[] f = line.fields();
            if (f[0].equals("GRAPH")) {
                graph = new Graph(f[1], defaults);
                graphs.add(graph);
            } else if (f[0].equals("END")) {
                if (graph.error == null && graph.nodes.isEmpty())
                    graph.error = new Error("no_nodes", line.number());
            } else if (graph.error == null) {
                String error = graph.accept(f);
                if (error != null)
                    graph.error = new Error(error, line.number());
            }
        }
        return graphs;
    }
}
final class AcyclicLayering {
    record Neighbors(List<List<Integer>> upper, List<List<Integer>> lower) {}
    record Promotion(int round, int vertex, int difference) {}
    record Result(int[] heights, int[] labels, int dummiesBefore, int rounds,
                  List<Promotion> promotions) {}
    static List<List<Integer>> lists(int count) {
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < count; i++)
            result.add(new ArrayList<>());
        return result;
    }
    static Neighbors neighbors(int count, List<GraphIo.Pair> edges) {
        List<List<Integer>> upper = lists(count), lower = lists(count);
        for (GraphIo.Pair edge : edges) {
            lower.get(edge.first()).add(edge.second());
            upper.get(edge.second()).add(edge.first());
        }
        return new Neighbors(upper, lower);
    }
    static List<Integer> acyclicOrder(int count, List<GraphIo.Pair> edges) {
        Neighbors neighbors = neighbors(count, edges);
        Set<Integer> remaining = new TreeSet<>();
        for (int i = 0; i < count; i++)
            remaining.add(i);
        List<Integer> head = new ArrayList<>(), tail = new ArrayList<>();
        while (!remaining.isEmpty()) {
            int[] in = new int[count], out = new int[count];
            Integer sink = null, source = null;
            int best = -1, bestDifference = Integer.MIN_VALUE;
            for (int v : remaining) {
                for (int u : neighbors.upper().get(v))
                    if (remaining.contains(u))
                        in[v]++;
                for (int w : neighbors.lower().get(v))
                    if (remaining.contains(w))
                        out[v]++;
                if (out[v] == 0 && sink == null)
                    sink = v;
                if (in[v] == 0 && source == null)
                    source = v;
                if (out[v] - in[v] > bestDifference) {
                    best = v;
                    bestDifference = out[v] - in[v];
                }
            }
            int chosen;
            if (sink != null) {
                chosen = sink;
                tail.addFirst(chosen);
            } else {
                chosen = source == null ? best : source;
                head.add(chosen);
            }
            remaining.remove(chosen);
        }
        head.addAll(tail);
        return head;
    }
    static final class Assignment {
        int count;
        Neighbors neighbors;
        int[] heights;
        Assignment(int count, Neighbors neighbors) {
            this.count = count;
            this.neighbors = neighbors;
            heights = new int[count];
            Arrays.fill(heights, -1);
        }
    }
    static Result assign(int count, List<GraphIo.Pair> edges, GraphIo.Settings settings) {
        Neighbors neighbors = neighbors(count, edges);
        Assignment assignment = new Assignment(count, neighbors);
        int[] heights = assignment.heights, labels = null;
        if (settings.layering.equals("coffman")) {
        } else
            for (int i = 0; i < count; i++)
                for (int v = 0; v < count; v++)
                    if (heights[v] < 0) {
                        boolean ready = true;
                        int height = 0;
                        for (int w : neighbors.lower().get(v)) {
                            if (heights[w] < 0)
                                ready = false;
                            height = Math.max(height, heights[w] + 1);
                        }
                        if (ready) {
                            heights[v] = height;
                            break;
                        }
                    }
        int dummiesBefore = 0;
        for (GraphIo.Pair edge : edges)
            dummiesBefore += heights[edge.first()] - heights[edge.second()] - 1;
        int rounds = 0;
        List<Promotion> promotions = new ArrayList<>();
        if (settings.promotion)
            while (true) {
            }
        return new Result(heights, labels, dummiesBefore, rounds, promotions);
    }
}
final class Crossing {
    record Segment(int upper, int lower, int edge) {}
    record PositionPair(int first, int second) {}
    static int[] positions(List<List<Integer>> orders) {
        int count = 0;
        for (List<Integer> layer : orders)
            count += layer.size();
        int[] positions = new int[count];
        for (List<Integer> layer : orders)
            for (int i = 0; i < layer.size(); i++)
                positions[layer.get(i)] = i;
        return positions;
    }
    static int accumulator(List<Segment> segments, int[] position, int lowerSize) {
        int capacity = 1;
        while (capacity < lowerSize)
            capacity *= 2;
        int[] tree = new int[2 * capacity - 1];
        List<PositionPair> pairs = new ArrayList<>();
        for (Segment segment : segments)
            pairs.add(new PositionPair(position[segment.upper()], position[segment.lower()]));
        pairs.sort(
            Comparator.comparingInt(PositionPair::first).thenComparingInt(PositionPair::second));
        int count = 0;
        for (PositionPair pair : pairs) {
            int index = pair.second() + capacity - 1;
            tree[index]++;
            while (index > 0) {
                if (index % 2 == 1)
                    count += tree[index + 1];
                index = (index - 1) / 2;
                tree[index]++;
            }
        }
        return count;
    }
    static int bruteForce(List<Segment> segments, int[] position) {
        int count = 0;
        for (int i = 0; i < segments.size(); i++)
            for (int j = i + 1; j < segments.size(); j++) {
                Segment a = segments.get(i), b = segments.get(j);
                if ((position[a.upper()] - position[b.upper()]) *
                        (position[a.lower()] - position[b.lower()]) <
                    0)
                    count++;
            }
        return count;
    }
    static int[] gapCounts(List<List<Segment>> gaps, List<List<Integer>> orders) {
        int[] position = positions(orders), counts = new int[gaps.size()];
        for (int i = 0; i < gaps.size(); i++)
            counts[i] = accumulator(gaps.get(i), position, orders.get(i + 1).size());
        return counts;
    }
    static int total(List<List<Segment>> gaps, List<List<Integer>> orders) {
        int total = 0;
        for (int value : gapCounts(gaps, orders))
            total += value;
        return total;
    }
    static int localCost(List<List<Segment>> gaps, List<List<Integer>> orders, int layer) {
        int[] position = positions(orders);
        int total = 0;
        for (int gap : new int[] {layer - 1, layer})
            if (gap >= 0 && gap < gaps.size())
                total += accumulator(gaps.get(gap), position, orders.get(gap + 1).size());
        return total;
    }
    static int adjacentCost(int first, int second, List<List<Integer>> upper,
                            List<List<Integer>> lower, int[] position) {
        int count = 0;
        for (List<List<Integer>> neighbors : List.of(upper, lower))
            for (int a : neighbors.get(first))
                for (int b : neighbors.get(second))
                    if (position[a] > position[b])
                        count++;
        return count;
    }
}
final class Coordinates {
    static final List<String> VARIANTS = List.of("ul", "ur", "dl", "dr");
    record Alignment(int[] root, List<List<Integer>> scan) {}
    record Compact(int[] coordinates, int blocks) {}
    record Result(int[] x, int[] left, int[] right, int[][] aligned, int[] blocks, int[] widths,
                  int smallest, Set<GraphIo.Pair> conflicts) {}
    static Result assign(List<List<Integer>> orders, List<List<Integer>> upper,
                         List<List<Integer>> lower, List<Integer> widths, int nodeCount,
                         GraphIo.Settings settings) {
        int count = widths.size();
        int[] left = new int[count], right = new int[count];
        if (settings.direction.equals("TB") || settings.direction.equals("BT"))
            for (int v = 0; v < count; v++) {
                left[v] = (widths.get(v) - 1) / 2;
                right[v] = widths.get(v) - 1 - left[v];
            }
        int[] x = new int[count];
        int minimum = Integer.MAX_VALUE;
        for (int v = 0; v < count; v++) {
            int[] values = {layouts[0][v], layouts[1][v], layouts[2][v], layouts[3][v]};
            Arrays.sort(values);
            x[v] = Math.floorDiv(values[1] + values[2], 2);
            minimum = Math.min(minimum, x[v] - left[v]);
        }
        for (int v = 0; v < count; v++)
            x[v] -= minimum;
        return new Result(x, left, right, layouts, blocks, spans, smallest, conflicts);
    }
final class Canvas {
    record Position(int main, int secondary) {}
    record Cell(int row, int column) {
        public String toString() { return row + "," + column; }
    }
    String direction;
    int mainLength, rows, columns;
    boolean vertical;
    byte[][] lines;
    char[][] arrows, boxes;
    boolean[][] highlighted;
    char mainCharacter, secondaryCharacter;
    Canvas(String direction, int mainLength, int secondaryLength) {
        this.direction = direction;
        this.mainLength = mainLength;
        vertical = direction.equals("TB") || direction.equals("BT");
        rows = vertical ? mainLength : secondaryLength;
        columns = vertical ? secondaryLength : mainLength;
        lines = new byte[rows][columns];
        arrows = new char[rows][columns];
        boxes = new char[rows][columns];
        highlighted = new boolean[rows][columns];
        mainCharacter = vertical ? '|' : '-';
        secondaryCharacter = vertical ? '-' : '|';
    }
    Cell cell(int main, int secondary) {
        if (direction.equals("BT") || direction.equals("RL"))
            main = mainLength - 1 - main;
        return vertical ? new Cell(main, secondary) : new Cell(secondary, main);
    }
    void addLine(int main, int secondary, char character) {
        Cell cell = cell(main, secondary);
        int bit = character == '|' ? 1 : character == '-' ? 2 : 4;
        lines[cell.row()][cell.column()] |= (byte)bit;
    }
    void mainLine(int start, int end, int secondary) {
        for (int main = start; main <= end; main++)
            addLine(main, secondary, mainCharacter);
    }
    void segment(int start, int gap, int first, int second, Integer offset) {
        if (first == second) {
            mainLine(start, start + gap - 1, first);
            return;
        }
        mainLine(start, start + offset - 1, first);
        addLine(start + offset, first, '+');
        addLine(start + offset, second, '+');
        for (int secondary = Math.min(first, second) + 1; secondary < Math.max(first, second);
             secondary++)
            addLine(start + offset, secondary, secondaryCharacter);
        mainLine(start + offset + 1, start + gap - 1, second);
    }
    void arrow(Position point, boolean reversed) {
        Cell cell = cell(point.main(), point.secondary());
        char character = switch (direction) {
            case "TB" -> reversed ? '^' : 'v';
            case "BT" -> reversed ? 'v' : '^';
            case "LR" -> reversed ? '<' : '>';
            default -> reversed ? '>' : '<';
        };
        arrows[cell.row()][cell.column()] = character;
    }
    void box(String label, int bandStart, int coordinate, int left, boolean onPath) {
        String text = onPath ? "{" + label + "}" : "[" + label + "]";
        Cell start;
        if (vertical)
            start = cell(bandStart, coordinate - left);
        else
            start = new Cell(coordinate, direction.equals("LR")
                                             ? bandStart
                                             : mainLength - bandStart - text.length());
        for (int i = 0; i < text.length(); i++)
            boxes[start.row()][start.column() + i] = text.charAt(i);
    }
    char character(int row, int column) {
        if (boxes[row][column] != 0)
            return boxes[row][column];
        if (arrows[row][column] != 0)
            return arrows[row][column];
        if (highlighted[row][column])
            return '#';
        return switch (lines[row][column]) {
            case 0 -> ' ';
            case 1 -> '|';
            case 2 -> '-';
            default -> '+';
        };
    }
    int crossingCells() {
        int count = 0;
        for (byte[] row : lines)
            for (byte bits : row)
                if ((bits & 3) == 3)
                    count++;
        return count;
    }
    List<String> drawingLines() {
        List<String> output = new ArrayList<>();
        StringBuilder ruler = new StringBuilder("    ");
        for (int column = 0; column < columns; column++)
            ruler.append(column % 10);
        output.add(ruler.toString());
        for (int row = 0; row < rows; row++) {
            StringBuilder line = new StringBuilder(String.format(Locale.ROOT, "%3d ", row));
            for (int column = 0; column < columns; column++)
                line.append(character(row, column));
            while (!line.isEmpty() && line.charAt(line.length() - 1) == ' ')
                line.setLength(line.length() - 1);
            output.add(line.toString());
        }
        return output;
    }
}
public final class Main {
    static final class Edge {
        int number, source, target, upper, lower, span, crossings, bends, length;
        boolean reversed, transitive;
        List<Integer> chain = new ArrayList<>();
        List<Canvas.Cell> route = new ArrayList<>();
        Canvas.Position upperEndpoint, lowerEndpoint;
        Edge(int number, int source, int target) {
            this.number = number;
            this.source = source;
            this.target = target;
            upper = source;
            lower = target;
        }
    }
    record Sweep(int run, int sweep, String direction, int moved, int swaps, int crossings) {}
    record Sift(int round, int moves, int crossings) {}
    record Key(int numerator, int denominator) {}
    record BusKey(boolean upper, int vertex) {}
    record Bus(BusKey key, List<Crossing.Segment> segments, int low, int high, int coordinate) {}
    record Tracks(int count, int gap, Map<GraphIo.Pair, Integer> offsets) {}
    static List<List<Integer>> copyOrder(List<List<Integer>> orders) {
